func requireGoText(value, name string) error {
	if value == "" {
		return fmt.Errorf("%s must not be empty", name)
	}
	if !utf8.ValidString(value) {
		return fmt.Errorf("%s must be valid UTF-8", name)
	}
	return nil
}

func requireGoBytes(value []byte, name string, length int) error {
	if len(value) == 0 {
		return fmt.Errorf("%s must not be empty", name)
	}
	if length >= 0 && len(value) != length {
		return fmt.Errorf("%s must contain exactly %d bytes", name, length)
	}
	return nil
}

func requireGoUint(value uint64, name string, minimum, maximum uint64) error {
	if value < minimum {
		return fmt.Errorf("%s must be at least %d", name, minimum)
	}
	if maximum != 0 && value > maximum {
		return fmt.Errorf("%s must be at most %d", name, maximum)
	}
	return nil
}

